// ─── FIREBASE : fusion locale ↔ cloud (évite d'écraser des données) ───────────
function mergeStates(local, cloud) {
  if (!cloud) return local;
  if (!local) return cloud;
  const norm = s => (s||"").toLowerCase().trim();
  // Collection : union par nom (on garde la première occurrence trouvée)
  const map = new Map();
  // Local d'abord : on garde les objets qui ont la photo (stockée localement)
  (local.collection||[]).forEach(a => {
    const k = norm(a && a.nom);
    if (k && !map.has(k)) map.set(k, a);
  });
  // Cloud ensuite : ajoute les animaux d'autres appareils, ou complète une photo manquante
  (cloud.collection||[]).forEach(a => {
    const k = norm(a && a.nom);
    if (!k) return;
    if (!map.has(k)) map.set(k, a);
    else if (!map.get(k).photo && a.photo) map.set(k, a);
  });
  const collection = [...map.values()];
  // Streak : compteur le plus haut + date la plus récente
  const ls = local.streak, cs = cloud.streak;
  let streak = ls || cs || null;
  if (ls && cs) {
    const base = (cs.count > ls.count) ? cs : ls;
    const last = (ls.last > cs.last) ? ls.last : cs.last;
    streak = { ...base, last };
  }
  const bonusXp = Math.max(local.bonusXp||0, cloud.bonusXp||0);
  const unlockedSecrets = [...new Set([...(local.unlockedSecrets||[]), ...(cloud.unlockedSecrets||[])])];
  // dailyDone : fusion par date, max sur chaque compteur
  const dailyDone = {};
  const days = new Set([...Object.keys(local.dailyDone||{}), ...Object.keys(cloud.dailyDone||{})]);
  days.forEach(d => {
    const l = (local.dailyDone||{})[d] || {};
    const c = (cloud.dailyDone||{})[d] || {};
    const ks = new Set([...Object.keys(l), ...Object.keys(c)]);
    const m = {};
    ks.forEach(k => { m[k] = Math.max(l[k]||0, c[k]||0); });
    dailyDone[d] = m;
  });
  return { collection, streak, dailyDone, unlockedSecrets, bonusXp };
}

