// Compresse une image base64 en une petite vignette (~300px) pour tenir dans localStorage
function compressImage(dataUrl, maxSize=320, quality=0.7) {
  return new Promise((resolve) => {
    try {
      const img = new Image();
      img.onload = () => {
        const ratio = Math.min(maxSize/img.width, maxSize/img.height, 1);
        const w = Math.round(img.width * ratio);
        const h = Math.round(img.height * ratio);
        const canvas = document.createElement("canvas");
        canvas.width = w; canvas.height = h;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, w, h);
        resolve(canvas.toDataURL("image/jpeg", quality));
      };
      img.onerror = () => resolve(dataUrl); // en cas d'échec, on garde l'original
      img.src = dataUrl;
    } catch {
      resolve(dataUrl);
    }
  });
}

