// ─── PARTAGE DE FICHE (génère une carte image via canvas) ────────────────────
async function shareCard(animal) {
  try {
    const r = getRarity(animal.rarete);
    const W = 600, H = 800;
    const canvas = document.createElement("canvas");
    canvas.width = W; canvas.height = H;
    const ctx = canvas.getContext("2d");

    // Fond dégradé
    const grad = ctx.createLinearGradient(0, 0, 0, H);
    grad.addColorStop(0, "#f0faf0");
    grad.addColorStop(1, "#e3f2fd");
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, W, H);

    // Bordure couleur rareté
    ctx.strokeStyle = r.color;
    ctx.lineWidth = 16;
    ctx.strokeRect(8, 8, W - 16, H - 16);

    // Bandeau titre
    ctx.fillStyle = r.color;
    ctx.fillRect(24, 24, W - 48, 70);
    ctx.fillStyle = "white";
    ctx.font = "bold 34px sans-serif";
    ctx.textAlign = "center";
    ctx.fillText("🌿 WildDex", W / 2, 70);

    // Photo de l'animal (carrée, centrée)
    const img = new Image();
    img.src = animal.photo;
    await new Promise(res => { img.onload = res; img.onerror = res; });
    const imgSize = 360;
    const ix = (W - imgSize) / 2, iy = 120;
    ctx.save();
    ctx.beginPath();
    ctx.roundRect(ix, iy, imgSize, imgSize, 24);
    ctx.clip();
    // crop centré
    const ratio = Math.max(imgSize / img.width, imgSize / img.height);
    const dw = img.width * ratio, dh = img.height * ratio;
    ctx.drawImage(img, ix + (imgSize - dw) / 2, iy + (imgSize - dh) / 2, dw, dh);
    ctx.restore();
    ctx.strokeStyle = r.color;
    ctx.lineWidth = 6;
    ctx.beginPath();
    ctx.roundRect(ix, iy, imgSize, imgSize, 24);
    ctx.stroke();

    // Nom
    ctx.fillStyle = "#2d3436";
    ctx.font = "bold 40px sans-serif";
    ctx.fillText(animal.nom || "Animal", W / 2, 540);

    // Nom scientifique
    ctx.fillStyle = "#636e72";
    ctx.font = "italic 22px sans-serif";
    ctx.fillText(animal.nom_scientifique || "", W / 2, 572);

    // Rareté
    ctx.fillStyle = r.color;
    ctx.font = "bold 26px sans-serif";
    ctx.fillText("★ " + r.label, W / 2, 620);

    // Infos
    ctx.fillStyle = "#2d3436";
    ctx.font = "20px sans-serif";
    ctx.fillText(`${animal.type || ""}  •  ${animal.habitat || ""}`, W / 2, 660);
    ctx.fillText(`${animal.taille || ""}  •  ${animal.poids || ""}`, W / 2, 690);

    // Pied de page
    ctx.fillStyle = "#aaa";
    ctx.font = "18px sans-serif";
    ctx.fillText("Capturé le " + (animal.date || ""), W / 2, 750);

    // Convertit en blob
    const blob = await new Promise(res => canvas.toBlob(res, "image/png"));
    const file = new File([blob], `wilddex-${animal.nom || "animal"}.png`, { type: "image/png" });

    // Partage natif si dispo (mobile), sinon téléchargement
    if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
      await navigator.share({
        files: [file],
        title: `J'ai découvert un ${animal.nom} !`,
        text: `Regarde ma découverte WildDex : ${animal.nom} 🌿`,
      });
    } else {
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = file.name;
      a.click();
      URL.revokeObjectURL(url);
    }
  } catch (e) {
    console.error("Partage échoué:", e);
  }
}

