const LEVELS = [
  { lvl:1, min:0,    title:"Apprenti",          icon:"🌱" },
  { lvl:2, min:50,   title:"Curieux",           icon:"🔍" },
  { lvl:3, min:150,  title:"Observateur",       icon:"👁️" },
  { lvl:4, min:300,  title:"Pisteur",           icon:"🐾" },
  { lvl:5, min:500,  title:"Naturaliste",       icon:"🌿" },
  { lvl:6, min:800,  title:"Explorateur",       icon:"🗺️" },
  { lvl:7, min:1200, title:"Expert",            icon:"🎓" },
  { lvl:8, min:1800, title:"Maître naturaliste",icon:"👑" },
];
function levelInfo(xp) {
  let current = LEVELS[0];
  for (const l of LEVELS) if (xp >= l.min) current = l;
  const next = LEVELS.find(l => l.min > xp) || null;
  const span = next ? next.min - current.min : 1;
  const into = xp - current.min;
  const progress = next ? Math.min(1, into / span) : 1;
  return { current, next, progress, xp };
}

