const CHALLENGES = [
  { id:"bird",    text:"Trouve un oiseau aujourd'hui !",       icon:"🐦", check:a=>(a.type||"").toLowerCase()==="oiseau" },
  { id:"mammal",  text:"Repère un mammifère !",                icon:"🐾", check:a=>(a.type||"").toLowerCase()==="mammifère" },
  { id:"insect",  text:"Déniche un insecte !",                 icon:"🐛", check:a=>(a.type||"").toLowerCase()==="insecte" },
  { id:"rare",    text:"Capture un animal rare ou plus !",     icon:"💎", check:a=>["rare","très rare","légendaire"].includes((a.rarete||"").toLowerCase()) },
  { id:"any2",    text:"Découvre 2 animaux aujourd'hui !",     icon:"🔍", check:()=>true, count:2 },
];
// Choisit un défi déterministe selon la date (même défi toute la journée)
function challengeOfTheDay() {
  const seed = todayKey().split("-").reduce((s,n)=>s+parseInt(n),0);
  return CHALLENGES[seed % CHALLENGES.length];
}

// ─── VOIX (synthèse vocale) ──────────────────────────────────────────────────
const VOICE_KEY = "wilddex_voice";

function loadVoiceSettings() {
  try {
    return JSON.parse(localStorage.getItem(VOICE_KEY)) || { voiceURI:null, rate:0.95, pitch:1.1 };
  } catch {
    return { voiceURI:null, rate:0.95, pitch:1.1 };
  }
}
function saveVoiceSettings(s) {
  try { localStorage.setItem(VOICE_KEY, JSON.stringify(s)); } catch {}
}
// Récupère les voix françaises disponibles sur l'appareil
function getFrenchVoices() {
  if (!("speechSynthesis" in window)) return [];
  return window.speechSynthesis.getVoices().filter(v => v.lang && v.lang.toLowerCase().startsWith("fr"));
}
// Lit un texte avec les réglages choisis
function speakText(text, settings, onEnd) {
  if (!("speechSynthesis" in window)) return;
  window.speechSynthesis.cancel();
  const utt = new SpeechSynthesisUtterance(text);
  utt.lang = "fr-FR";
  utt.rate = settings?.rate ?? 0.95;
  utt.pitch = settings?.pitch ?? 1.1;
  if (settings?.voiceURI) {
    const v = window.speechSynthesis.getVoices().find(v => v.voiceURI === settings.voiceURI);
    if (v) utt.voice = v;
  }
  if (onEnd) utt.onend = onEnd;
  window.speechSynthesis.speak(utt);
}

async function analyzeImage(base64, mediaType) {
  const res = await fetch(WORKER_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      image: base64,
      mime_type: mediaType,
      system: SYSTEM_PROMPT,
    })
  });
  if (!res.ok) throw new Error(`Worker error ${res.status}`);
  const data = await res.json();

  // text peut être une chaîne ou un objet selon le modèle
  let raw = data.text;
  if (typeof raw !== "string") raw = JSON.stringify(raw);

  const clean = raw.replace(/```json|```/g, "").trim();

  // On extrait le JSON même s'il y a du texte autour
  const match = clean.match(/\{[\s\S]*\}/);
  return JSON.parse(match ? match[0] : clean);
}

