// src/firebase.js
import { initializeApp } from "firebase/app";
import {
  getAuth, GoogleAuthProvider, signInWithPopup,
  createUserWithEmailAndPassword, signInWithEmailAndPassword,
  signOut, onAuthStateChanged, deleteUser,
} from "firebase/auth";
import { getFirestore, doc, getDoc, setDoc, deleteDoc } from "firebase/firestore";

const firebaseConfig = {
  apiKey: "AIzaSyAX3U4ymn1aAffRjN9gEMO8fslxzIw9Rrc",
  authDomain: "wilddex-b56bf.firebaseapp.com",
  projectId: "wilddex-b56bf",
  storageBucket: "wilddex-b56bf.firebasestorage.app",
  messagingSenderId: "581734015443",
  appId: "1:581734015443:web:02e77365f030d29a5d0f26",
};

const app = initializeApp(firebaseConfig);
export const auth = getAuth(app);
export const db = getFirestore(app);
const googleProvider = new GoogleAuthProvider();

// --- Connexion ---
export const loginGoogle  = () => signInWithPopup(auth, googleProvider);
export const registerEmail = (email, pwd) => createUserWithEmailAndPassword(auth, email, pwd);
export const loginEmail    = (email, pwd) => signInWithEmailAndPassword(auth, email, pwd);
export const logout        = () => signOut(auth);
export const watchAuth     = (cb) => onAuthStateChanged(auth, cb);

// --- Sauvegarde cloud (Firestore) ---
export async function loadCloud(uid) {
  const snap = await getDoc(doc(db, "users", uid));
  return snap.exists() ? snap.data() : null;
}
export async function saveCloud(uid, data) {
  return setDoc(doc(db, "users", uid), data, { merge: true });
}

// --- Suppression de compte (obligatoire Play Store) ---
export async function deleteAccount() {
  const user = auth.currentUser;
  if (!user) return;
  await deleteDoc(doc(db, "users", user.uid));
  await deleteUser(user);
}